#!/bin/bash
# batch E1: generated by scripts/make_batch.py from tracks/kb/claims_tracks/decisions/E1.tsv; do not edit by hand
cd /data/haiyangw/nrpic/wt/kb || exit 2
fail=0
test -n "${NRPIC_RUN_DIR:-}" || { echo 'not inside nrpic-run'; exit 2; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py snapshot tracks/kb/claims_tracks/decisions/E1.tsv > "$NRPIC_RUN_DIR/before.json" || fail=1
python3 -I tracks/kb/claims_tracks/scripts/annotate.py annotate tracks/kb/claims_tracks/decisions/E1_annot.tsv || { echo FAILED annotate; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py rows tracks/kb/claims_tracks/decisions/E1.tsv "$NRPIC_RUN_DIR/before.json" "$NRPIC_RUN_ID" > "$NRPIC_RUN_DIR/ledger_rows.tsv" || fail=1
exit $fail
